        let bInputs = Inputs.vectors(H.Vector.self, seed: 0x799B_B5F4_6E90_3068)
        let cInputs = Inputs.vectors(H.Vector.self, seed: 0x799B_B8F4_6E90_3581)
        let dInputs = Inputs.vectors(H.Vector.self, seed: 0x799B_B7F4_6E90_33CE)
        for (a, b, c, d) in mixedQuadruples(
            aInputs,
            bInputs,
            cInputs,
            dInputs,
            seed: 0x0BA5_13D9_ED07_CF3D
        ) {
            let (_, portLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                unsafe H.appendInterleaved4(a, b, c, d, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 4 * H.laneCount) { output in
                H.appendInterleaved4(a, b, c, d, to: &output)
            }
            mismatches.check(
                portLanes,
                referenceLanes,
                "a: \(describe(a)), b: \(describe(b)), c: \(describe(c)), d: \(describe(d))"
            )
        }
        mismatches.record()
    }
}
